import{_ as t,o as e,c as n,ag as s}from"./chunks/framework.DUTPmUpA.js";const b=JSON.parse('{"title":"Настройка вашего дополнения для совместной работы","description":"","frontmatter":{"title":"Настройка вашего дополнения для совместной работы","author":"Perry"},"headers":[],"relativePath":"tools/setting-up-for-collaboration.md","filePath":"tools/setting-up-for-collaboration.md"}'),i={name:"tools/setting-up-for-collaboration.md"};function o(r,a,l,p,c,d){return e(),n("div",null,[...a[0]||(a[0]=[s(`<p>ка вашего дополнения для совместной работы</p><p>Разговаривая с разработчиками модов для Dota 2 или просто с разработчиками программного обеспечения в целом, вы часто слышите слова «репозитории», «контроль версий» и «git». Причина, по которой эти темы настолько популярны, заключается в том, что контроль версий — очень важная тема в разработке программного обеспечения, и если вы работаете над каким-либо программным обеспечением, вам СЛЕДУЕТ его использовать. В этой статье я попытаюсь, во-первых, разъяснить, что такое контроль версий, почему вы хотите его использовать и как я лично настроил его для Dota 2. Если вы прочтете ее до конца, я, возможно, даже расскажу вам несколько постыдных историй о том, как я узнал большую часть этого методом проб и ошибок.</p><h2 id="что-такое-контроль-версии" tabindex="-1">Что такое контроль версий <a class="header-anchor" href="#что-такое-контроль-версии" aria-label="Permalink to &quot;Что такое контроль версий&quot;">​</a></h2><p>Название уже выдает это, но контроль версий — это метод управления… ну, вашими версиями. Более полезным описанием было бы то, что контроль версий — это способ отслеживания различных версий и этапов разработки вашего программного обеспечения. Термин «репозиторий» используется для описания проекта, которым управляет какой-либо механизм контроля версий. По сути, у вас есть система, которая отслеживает любые изменения и гарантирует, что все, кто работает над программным обеспечением, могут одновременно работать над одной и той же версией этого программного обеспечения. Обычно это означает, что у вас есть «удаленный» сервер, на котором хранятся все файлы, и каждый раз, когда вы или кто-то другой вносите изменения, этот удаленный сервер знает об этом и может распространять эту версию среди других людей, работающих над программным обеспечением. Существует несколько методов контроля версий, популярные из них включают Git, SVN и Mercurial. В этой статье основное внимание будет уделено Git, поскольку, на мой взгляд, это самый удобный метод.</p><h2 id="почему-вам-следует-использовать-контроль-версии" tabindex="-1">Почему вам следует использовать контроль версий <a class="header-anchor" href="#почему-вам-следует-использовать-контроль-версии" aria-label="Permalink to &quot;Почему вам следует использовать контроль версий&quot;">​</a></h2><p>Причин использовать контроль версий много, я перечислю те, которые лично считаю наиболее важными:</p><ul><li><strong>Совместная работа</strong>: <br> Контроль версий позволяет нескольким людям работать над одними и теми же файлами, не отменяя изменений друг друга. Git просто просматривает изменения отдельных строк, и когда два человека редактируют одну и ту же строку, он автоматически обнаруживает конфликт и просит его устранить.</li><li><strong>Оглядываясь назад</strong>: <br> Используя контроль версий, вы сохраняете разные версии вашего программного обеспечения. Это означает, что позже вы всегда сможете вернуться к предыдущей версии. Это означает, что вы можете вернуться к более старой версии, если что-то серьезно испорчено, или вы можете просто просмотреть код, который у вас был ранее, и сравнить его с текущим кодом.</li><li><strong>Резервное копирование</strong>: <br> Как уже говорилось ранее, большинство систем контроля версий имеют пульт, который отслеживает все изменения в программном обеспечении. Это означает, что если ваш жесткий диск выйдет из строя, вы всегда сможете получить программное обеспечение с пульта дистанционного управления, как будто ничего не произошло.</li></ul><p>Я также хотел бы развеять некоторые (неправильные) заблуждения относительно того, почему вы <em>не</em> хотите_ использовать контроль версий:</p><ul><li><em>&quot;Это программное обеспечение настолько простое, что не требует контроля версий&quot;</em>: <br> Я должен признать, что в некоторых случаях это правда, обычно, если вы планируете работать над кодом только один или два дня, вам это сойдет с рук. Однако, если вы планируете работать над программным обеспечением более двух дней, вам следует использовать контроль версий, чтобы отслеживать процесс разработки. Одна только резервная функция контроля версий делает это полезным.</li><li><em>&quot;Я единственный человек, работающий над этим кодом&quot;</em>: <br> Поверьте мне, это, пожалуй, худший аргумент в пользу не использования контроля версий. Как и в предыдущем пункте, сама по себе функция резервного копирования делает ее целесообразным использовать. Более того, разделение вашего программного обеспечения на разные версии очень полезно для процесса разработки.</li></ul><h2 id="гит" tabindex="-1">Гит <a class="header-anchor" href="#гит" aria-label="Permalink to &quot;Гит&quot;">​</a></h2><p>Как упоминалось ранее, эта статья будет посвящена использованию Git. Так что же такое Git? Git — это метод контроля версий, при котором все сотрудники имеют собственный репозиторий на своем компьютере. Всякий раз, когда они фиксируют изменение, обновляется только их репозиторий. Как только разработчик будет доволен тем, что у него есть, он может отправить все внесенные им изменения на удаленный компьютер, чтобы другие сотрудники могли их извлечь. Git также допускает использование разных веток. Это означает, что вы можете одновременно иметь две ветки с активными разными версиями вашего программного обеспечения, а изменения, внесенные разработчиками, применяются только к одной ветке. Ветви также можно объединить, чтобы изменения, внесенные в одну ветку, также применялись в другой ветке. Типичным примером этого является программное обеспечение, имеющее главную ветку и ветку разработки. При разработке разработчики переходят к ветке разработки, и как только программное обеспечение достигает основной вехи, они объединяют ветку разработки с основной веткой, так что в ней есть только основные версии вех. Тем временем разработчики могут снова продолжить работу над веткой разработки.</p><h2 id="как-использовать-git" tabindex="-1">Как использовать Git <a class="header-anchor" href="#как-использовать-git" aria-label="Permalink to &quot;Как использовать Git&quot;">​</a></h2><p>В Google можно найти множество руководств по git, однако здесь я приведу краткое изложение основных концепций. Прежде всего, <strong>фиксируйте</strong> каждый раз, когда вы хотите сохранить изменения. Коммит — это, по сути, версия вашего программного обеспечения, вы всегда можете вернуться к своим коммитам позже. <strong>Pulling</strong> — это получение всех коммитов для какой-либо ветки с вашего удаленного компьютера. Таким образом, вы также получите изменения вашего соавтора. С другой стороны, <strong>толкать</strong> — это противоположность тянуть. Он передает вашу историю коммитов на удаленный компьютер, чтобы другие соавторы могли получить ее. Помните: всегда тяните, прежде чем толкать!</p><p><strong>Конфликты слияния.</strong> Несмотря на то, что Git отслеживает отдельные строки, могут возникать ситуации, когда несколько соавторов изменяли одни и те же строки. При извлечении данных с удаленного компьютера git автоматически обнаружит так называемые «конфликты слияния» и попросит вас разрешить их. Основной способ разрешения конфликтов слияния — открыть файл, в котором имеется конфликт. Вы увидите несколько строк, которые в основном выглядят следующим образом:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</span></span>
<span class="line"><span>nine</span></span>
<span class="line"><span>=======</span></span>
<span class="line"><span>eight</span></span>
<span class="line"><span>&gt;&gt;&gt;&gt;&gt;&gt;&gt; branch-a</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>По сути, все, что находится между <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;HEAD</code> и <code>=====</code>, — это то, что у вас есть для этой линии, все, что находится между строкой <code>==========</code> и линией <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>, — это то, что вы извлекли с пульта. Разрешите конфликт, просто удалив все, кроме кода, который вы хотите сохранить. Это могут быть ваши вещи, вещи с пульта или даже и то, и другое! Фиксированный файл может выглядеть так (я решил оставить оба):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nine</span></span>
<span class="line"><span>eight</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="пульты" tabindex="-1">Пульты <a class="header-anchor" href="#пульты" aria-label="Permalink to &quot;Пульты&quot;">​</a></h2><p>Удаленный доступ — это, по сути, удаленное место, в котором хранится ваше программное обеспечение и его различные версии и которые используются для передачи версий всем участникам этой части программного обеспечения. Существует множество различных сервисов, предоставляющих пульты дистанционного управления, но для моддинга Dota 2 я бы рекомендовал использовать Git с одним из этих двух сервисов:</p><p><a href="https://github.com/" target="_blank" rel="noreferrer">Github</a> — очень дружелюбный к пользователю (и нубу) провайдер git. Github имеет приятный интерфейс и очень простой в использовании клиент с графическим интерфейсом для Windows. Обратите внимание, что в этом клиенте представлены только самые основы. Если вам нужны более сложные вещи, вам придется использовать командную строку. На github уже есть много модов для Dota 2, вы можете просто поискать их на сайте и попробовать!</p><p><a href="https://bitbucket.org/" target="_blank" rel="noreferrer">BitBucket</a> — Bitbucket также предлагает удаленный сервис, аналогичный github. Bitbucket не так дружелюбен к новичкам, как Github. Если вы хотите использовать Bitbucket, вы не сможете использовать клиент Github для Windows, подробнее об этом позже.</p><h2 id="git-клиенты" tabindex="-1">Git-клиенты <a class="header-anchor" href="#git-клиенты" aria-label="Permalink to &quot;Git-клиенты&quot;">​</a></h2><p>Существует три основных метода работы с git:</p><ul><li><a href="https://www.sourcetreeapp.com/" target="_blank" rel="noreferrer">SourceTree</a> - Мой личный фаворит. Sourcetree — это клиент git с графическим интерфейсом. Поначалу это может показаться немного пугающим, так как вариантов очень много, но через некоторое время вы автоматически узнаете, как это работает. Работает с любым пультом git и предоставляет множество функций.</li><li><a href="https://windows.github.com/" target="_blank" rel="noreferrer">Github client</a> - Github предоставляет настольному клиенту приятный и очень удобный интерфейс. Недостаток этого клиента заключается в том, что он работает только с пультами GitHub и позволяет использовать только минимум функций git без открытия командной строки. Также работает только на Windows.</li><li><a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git command line</a> - Git в основном управляется из командной строки, поэтому, конечно, вы можете вообще не использовать какие-либо модные клиенты, а просто вводить команды непосредственно в командную строку. Другие клиенты — это, по сути, просто пользовательские интерфейсы, созданные на основе этого.</li></ul><h2 id="как-настроить-репозитории-модов-dota-2" tabindex="-1">Как настроить репозиторий модов dota 2 <a class="header-anchor" href="#как-настроить-репозитории-модов-dota-2" aria-label="Permalink to &quot;Как настроить репозиторий модов dota 2&quot;">​</a></h2><p>Настройка репозитория модов Dota 2 не совсем тривиальна, поскольку вы хотите включить два каталога в разные места вместо того, чтобы создавать репозиторий только в одном каталоге. Вы, конечно, можете создать репозиторий для своей папки dota_ugc, но в идеале вам хотелось бы иметь один репозиторий для каждого проекта, вместо того, чтобы отслеживать изменения всех них в одном репозитории.</p><p>Итак, вот мое решение: Я создал каталог где-то на своем жестком диске, неважно где, и назвал его «Моды Dota 2». Внутри этого каталога я создал разные каталоги для каждого созданного мною мода, так что у меня будет каталог Bomberman, каталог Invoker Warfare и т. д. и т. п. Итак, как мне разместить здесь файлы мода? Ответ — символические ссылки или, сокращенно, символические ссылки. Символическая ссылка — это, по сути, ссылка на другой каталог на вашем компьютере. Это означает, что вы можете иметь один и тот же каталог в двух местах вашей файловой системы. Изменение содержимого этого каталога повлияет на файлы в каталоге в обоих местах. Каталог репозитория будет выглядеть примерно так:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>myproject/</span></span>
<span class="line"><span>├── game/          // symlink junction to dota 2 beta/game/dota_addons/myproject/</span></span>
<span class="line"><span>├── content/       // symlink junction to dota 2 beta/content/dota_addons/myproject</span></span>
<span class="line"><span>└── ...            // other files like documents, scripts, etc can go in myproject/ and your repository too</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="как-сделать-символические-ссылки-в-dota-2" tabindex="-1">Как сделать символические ссылки в Dota 2 <a class="header-anchor" href="#как-сделать-символические-ссылки-в-dota-2" aria-label="Permalink to &quot;Как сделать символические ссылки в Dota 2&quot;">​</a></h3><p>Внутри папки вашего мода откройте командное окно, щелкнув папку правой кнопкой мыши (убедитесь, что у вас не выбрано ни одного файла) и нажав «Открыть командное окно здесь». Теперь просто введите команды для каждой папки, которую вы хотите включить. Я покажу вам свои команды, но имейте в виду, что вам, возможно, придется изменить путь к вашим каталогам:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mklink /j &quot;game&quot; &quot;D:\\Program Files\\Steam\\steamapps\\common\\dota 2 beta\\dota_ugc\\game\\dota_addons\\bomberman&quot;</span></span>
<span class="line"><span>mklink /j &quot;content&quot; &quot;D:\\Program Files\\Steam\\steamapps\\common\\dota 2 beta\\dota_ugc\\content\\dota_addons\\bomberman&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Если вы все сделали правильно, вы должны теперь увидеть каталог с игрой и контентом внутри каталога вашего мода! Теперь вы можете просто создать репозиторий этого каталога, и он также должен автоматически учитывать содержимое ваших символически связанных каталогов. Дополнительным преимуществом этого метода является то, что вы также можете поместить в папку мода другие вещи, которые будут включены в систему контроля версий. Лично у меня там тоже есть каталог документов, в котором хранятся все документы, которые я создал, связанные с модом.</p><p><strong>Бонусный совет:</strong> Обязательно добавьте файл «thumnail_cache.bin» в свой gitignore. Это предотвращает раздувание вашего репозитория этим бесполезным файлом.</p>`,33)])])}const h=t(i,[["render",o]]);export{b as __pageData,h as default};
